import Icon from "./includes/Icon.tsrx";
import { bindGroup, bindValue, RippleMap, track, effect } from "ripple";
import * as v from "valibot";
import {
  type Bookmark,
  type ToastType,
  toastTypes,
  type ToastData,
  tabOptions,
  type TabOption,
  sortOptions,
  type SortOption,
  db,
} from "./includes/store.ts";
import { getHostname, getBlobUrl, formatDate } from "./includes/utils.ts";

type FormErrors = Partial<Record<"url" | "title" | "description" | "tags", string>>;

export component App() {
  const data = new RippleMap<string, Bookmark>();
  const toastsMap = new RippleMap<string, ToastData>();

  effect(() => {
    db.bookmarks.toArray().then((bookmarks) => {
      bookmarks.forEach((bm) => data.set(bm.id, bm));
    });
  });

  async function saveBookmark(bm: Bookmark) {
    data.set(bm.id, bm);
    await db.bookmarks.put(bm);
  }

  async function deleteBookmark(id: string) {
    data.delete(id);
    await db.bookmarks.delete(id);
  }

  function showToast(message: string, type: ToastType = "info", action?: ToastData["action"]) {
    const id = crypto.randomUUID();
    toastsMap.set(id, { id, message, type, action });
    setTimeout(() => {
      toastsMap.delete(id);
    }, 5000);
  }

  let &[toasts] = track(() => [...toastsMap.values()]);

  let &[tagCounts] = track(() => {
    const counts: Record<string, number> = {};
    [...data.values()].forEach((bookmark) => {
      bookmark.tags.forEach((tag) => (counts[tag] = (counts[tag] ?? 0) + 1));
    });

    return Object.fromEntries(Object.entries(counts).sort(([a], [b]) => a.localeCompare(b)));
  });

  let &[tab] = track<TabOption>(tabOptions[0]);
  let &[filters, filtersRef] = track<string[]>([]);
  let &[sort] = track<SortOption>(sortOptions[0]);
  let &[search, searchRef] = track("");

  let &[bookmarks] = track(() => {
    const _tab = tab;
    const _tags = filters;
    const _search = search.toLowerCase();
    const _sort = sort;

    return [...data.values()].filter((bookmark) => {
      if (bookmark.isArchived !== (_tab === "Archived")) return false;
      if (_tags.length > 0 && !_tags.every((t) => bookmark.tags.includes(t))) return false;
      if (_search && !bookmark.title.toLowerCase().includes(_search)) return false;
      return true;
    }).sort((a, b) => {
      if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;

      if (_sort === "Recently Visited") {
        const diff = (b.visitedAt ?? 0) - (a.visitedAt ?? 0);
        if (diff !== 0) return diff;
      } else if (_sort === "Most Visited") {
        const diff = b.visitCount - a.visitCount;
        if (diff !== 0) return diff;
      }

      // Fallback: recently added
      return b.createdAt - a.createdAt;
    });
  });

  let modal: HTMLDialogElement | undefined;
  let &[editItem] = track<Bookmark | null>(null);

  let &[url, urlRef] = track("");
  let &[title, titleRef] = track("");
  let &[desc, descRef] = track("");
  let &[draftTags] = track<string[]>([]);
  let &[tag, tagRef] = track("");
  let &[favicon] = track<Blob | null>(null);
  let &[loading] = track(false);

  const BookmarkFormSchema = v.object({
    url: v.pipe(
      v.string(),
      v.nonEmpty("URL is required."),
      v.regex(
        /^https?:\/\/(?:[\w-]+\.)+[a-zA-Z]{2,}(?:\/\S*)?$/,
        "Enter a valid URL starting with http or https.",
      ),
      v.url("Please enter a valid URL."),
    ),
    title: v.pipe(
      v.string(),
      v.nonEmpty("Title is required."),
      v.maxLength(100, "Title cannot exceed 100 characters."),
    ),
    description: v.pipe(
      v.string(),
      v.nonEmpty("Description is required."),
      v.maxLength(280, "Description cannot exceed 280 characters."),
    ),
    tags: v.pipe(
      v.array(
        v.pipe(v.string(), v.maxLength(30, "A tag cannot exceed 30 characters.")),
        "Tags must be an array.",
      ),
      v.minLength(1, "At least one tag is required."),
      v.maxLength(5, "At max five tags can be added."),
    ),
  });

  let &[errors] = track<FormErrors>({});

  async function fetchMeta() {
    if (!url) return;

    loading = true;
    try {
      const response = await fetch(`https://api.microlink.io/?url=${encodeURIComponent(url)}`);
      const result = await response.json();

      if (result.status === "success" && result.data) {
        if (result.data.title) title = result.data.title;
        if (result.data.description) desc = result.data.description;
        if (result.data.logo?.url) {
          try {
            const imgRes = await fetch(
              `https://images.weserv.nl/?url=${encodeURIComponent(result.data.logo.url)}`,
            );
            favicon = await imgRes.blob();
          } catch (e) {
            console.error("Failed to fetch image blob:", e);
          }
        }
      }
    } catch (error) {
      console.error("Failed to fetch metadata:", error);
    } finally {
      loading = false;
    }
  }

  <div class="drawer lg:drawer-open h-dvh bg-base-300 text-base-content overflow-hidden">
    <input id="main-drawer" type="checkbox" class="drawer-toggle" />
    <div class="drawer-side z-40">
      <label for="main-drawer" aria-label="close sidebar" class="drawer-overlay" />
      <aside class="w-max flex flex-col border-r border-base-200 min-h-full">
        <div class="flex justify-between gap-5 p-4.5 items-center bg-base-100">
          <h1 class="flex  items-center gap-2">
            <Icon name="bookmark" class="inline text-primary" />
            <span class="text-xl font-extrabold tracking-tight text-primary">
              "Bookmark Manager"
            </span>
          </h1>
          <label for="main-drawer" class="btn btn-ghost btn-circle btn-xs lg:hidden">
            <Icon name="x" class="inline" />
          </label>
        </div>
        <nav>
          <menu class="menu w-full gap-0.5 px-2">
            for (const item of tabOptions; key item) {
              <li>
                <button
                  class={[
                    "rounded-lg",
                    tab === item && ["font-semibold bg-secondary text-secondary-content"],
                  ]}
                  onClick={() => (tab = item)}
                >
                  if (item === "Home") {
                    <Icon name="house" class="inline" />
                  } else {
                    <Icon name="archive" class="inline" />
                  }
                  {item}
                </button>
              </li>
            }
          </menu>
        </nav>
        <div class="flex-1 min-h-0 flex flex-col">
          <div class="flex justify-between items-center px-4 py-2">
            <h2 class="text-xs font-bold uppercase tracking-widest opacity-70">"Tags"</h2>
            if (filters.length > 0) {
              <button class="btn btn-xs btn-ghost opacity-70" onClick={() => (filters = [])}>
                "Reset"
              </button>
            }
          </div>
          <menu class="menu menu-sm w-full overflow-y-auto flex-1 px-2">
            for (const [tag, count] of Object.entries(tagCounts); key tag) {
              <li>
                <label class="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    value={tag}
                    {ref bindGroup(filtersRef)}
                    checked={filters.includes(tag)}
                    class="checkbox checkbox-sm checkbox-primary rounded"
                  />
                  <span class="flex-1">{tag}</span>
                  <span
                    class="text-xs text-neutral-content bg-neutral rounded-full w-6 h-6 flex items-center justify-center font-medium"
                  >
                    {count}
                  </span>
                </label>
              </li>
            }
          </menu>
        </div>
      </aside>
    </div>
    <div class="drawer-content flex flex-col h-dvh min-w-0">
      <main class="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header class="navbar bg-base-100 border-b border-base-200 px-4 gap-2 min-h-16">
          <div class="flex-none">
            <label for="main-drawer" class="btn btn-square btn-ghost lg:hidden">
              <Icon name="menu" class="inline" />
            </label>
          </div>
          <div class="flex-1 px-2 lg:px-0">
            <label class="input input-bordered flex items-center gap-2 w-full max-w-lg bg-base-100">
              <Icon name="search" class="inline opacity-70" />
              <input
                type="search"
                {ref bindValue(searchRef)}
                class="grow"
                placeholder="Search by title..."
              />
            </label>
          </div>
          <div class="flex-none flex items-center gap-3">
            <button
              class="btn btn-primary rounded-lg"
              onclick={() => {
                editItem = null;
                url = "";
                title = "";
                desc = "";
                draftTags = [];
                tag = "";
                errors = {};
                favicon = null;
                modal?.showModal();
              }}
            >
              <Icon name="plus" class="inline" />
              <span class="hidden sm:inline">"Add Bookmark"</span>
            </button>
          </div>
        </header>
        <section class="flex-1 overflow-y-auto p-6 lg:p-8">
          <div class="flex justify-between items-center mb-6">
            <h2 class="text-2xl font-bold tracking-tight">"All bookmarks"</h2>
            <div>
              <button
                class="btn bg-base-100 border-base-200 rounded-lg"
                popovertarget="popover-sortby"
                style="anchor-name:--anchor-sortby"
              >
                <Icon name="arrow-up-down" class="inline" />
                <span>"Sort by"</span>
              </button>
              <menu
                class="dropdown dropdown-end menu w-max rounded-box bg-base-100 shadow-sm"
                popover
                id="popover-sortby"
                style="position-anchor:--anchor-sortby"
              >
                for (const item of sortOptions; key item) {
                  <li>
                    <button
                      popovertarget="popover-sortby"
                      popovertargetaction="hide"
                      onClick={() => (sort = item)}
                    >
                      <span>{item}</span>

                      if (sort === item) {
                        <Icon name="check" class="ml-auto text-primary" />
                      }
                    </button>
                  </li>
                }
              </menu>
            </div>
          </div>
          <div class="gap-5 grid pb-4 grid-cols-1 md:grid-cols-2 xl:grid-cols-3">
            for (const item of bookmarks; key item.id) {
              <article
                class="card bg-base-100 border border-base-200 rounded-2xl hover:shadow-md transition-shadow duration-200 animate-fade-in-up"
              >
                <div class="card-body p-5 gap-3">
                  <header class="flex gap-3 items-start">
                    <figure class="border border-base-200 rounded-xl p-2.5 shrink-0">
                      <img src={getBlobUrl(item.favicon)} class="w-7 h-7 object-contain" />
                    </figure>
                    <div class="min-w-0 flex-1">
                      <h3 class="font-semibold text-base truncate">{item.title}</h3>
                      <p class="text-xs opacity-70 truncate">
                        {item.hostname}
                      </p>
                    </div>
                    <div class="ml-auto shrink-0">
                      <button
                        class="btn btn-ghost btn-sm btn-circle rounded-lg"
                        popovertarget={"popover-actions-" + item.id}
                        style={"anchor-name:--anchor-actions-" + item.id}
                      >
                        <Icon name="ellipsis-vertical" class="inline" />
                      </button>
                      <menu
                        class="dropdown dropdown-end menu w-max rounded-box bg-base-100 shadow-sm"
                        popover
                        id={"popover-actions-" + item.id}
                        style={"position-anchor:--anchor-actions-" + item.id}
                      >
                        <li>
                          <button
                            popovertarget={"popover-actions-" + item.id}
                            popovertargetaction="hide"
                            onClick={() => {
                              const updated = {
                                ...item,
                                visitedAt: Date.now(),
                                visitCount: item.visitCount + 1,
                              };
                              saveBookmark(updated);
                              window.open(item.url, "_blank", "noopener,noreferrer");
                            }}
                          >
                            <Icon name="eye" class="inline" size={20} />
                            <span>"Visit"</span>
                          </button>
                        </li>
                        <li>
                          <button
                            popovertarget={"popover-actions-" + item.id}
                            popovertargetaction="hide"
                            onClick={async () => {
                              await navigator.clipboard.writeText(item.url);
                              showToast("URL copied to clipboard", "success");
                            }}
                          >
                            <Icon name="copy" class="inline" size={20} />
                            <span>"Copy URL"</span>
                          </button>
                        </li>
                        if (!item.isArchived) {
                          <li>
                            <button
                              popovertarget={"popover-actions-" + item.id}
                              popovertargetaction="hide"
                              onClick={() => {
                                const updated = { ...item, isPinned: !item.isPinned };
                                saveBookmark(updated);
                                showToast(
                                  updated.isPinned ? "Bookmark pinned to top" : "Bookmark unpinned",
                                  "success",
                                );
                              }}
                            >
                              if (item.isPinned) {
                                <Icon name="pin-off" class="inline" size={20} />
                                <span>"Unpin"</span>
                              } else {
                                <Icon name="pin" class="inline" size={20} />
                                <span>"Pin"</span>
                              }
                            </button>
                          </li>
                          <li>
                            <button
                              popovertarget={"popover-actions-" + item.id}
                              popovertargetaction="hide"
                              onclick={() => {
                                editItem = item;
                                url = item.url;
                                title = item.title;
                                desc = item.description;
                                draftTags = [...item.tags];
                                tag = "";
                                errors = {};
                                favicon = item.favicon;
                                modal?.showModal();
                              }}
                            >
                              <Icon name="pencil" class="inline" size={20} />
                              <span>"Edit"</span>
                            </button>
                          </li>
                        }
                        <li>
                          <button
                            popovertarget={"popover-actions-" + item.id}
                            popovertargetaction="hide"
                            onClick={() => {
                              const updated = { ...item, isArchived: !item.isArchived };
                              if (updated.isArchived) updated.isPinned = false;
                              saveBookmark(updated);
                              showToast(
                                updated.isArchived ? "Bookmark archived" : "Bookmark unarchived",
                                "info",
                              );
                            }}
                          >
                            if (item.isArchived) {
                              <Icon name="archive-restore" class="inline" size={20} />
                              <span>"Unarchive"</span>
                            } else {
                              <Icon name="archive" class="inline" size={20} />
                              <span>"Archive"</span>
                            }
                          </button>
                        </li>
                        if (item.isArchived) {
                          <li>
                            <button
                              popovertarget={"popover-actions-" + item.id}
                              popovertargetaction="hide"
                              onClick={() => {
                                deleteBookmark(item.id);
                                showToast("Bookmark deleted", "error", {
                                  label: "Undo",
                                  onClick: () => saveBookmark(item),
                                });
                              }}
                            >
                              <Icon name="trash" class="inline" size={20} />
                              <span>"Delete"</span>
                            </button>
                          </li>
                        }
                      </menu>
                    </div>
                  </header>
                  <hr />
                  <p class="text-sm opacity-80 line-clamp-3">{item.description}</p>
                  <div class="flex flex-wrap gap-1.5">
                    for (const it of item.tags; key it) {
                      <span
                        class="text-xs font-medium px-2.5 py-1 rounded-md bg-neutral text-neutral-content"
                      >
                        {it}
                      </span>
                    }
                  </div>
                  <hr />
                  <footer class="flex items-center gap-4 mt-2 text-xs opacity-70">
                    <div class="flex items-center gap-1">
                      <Icon name="eye" size={18} class="inline" />
                      <span>
                        {item.visitCount}
                      </span>
                    </div>
                    <div class="flex items-center gap-1">
                      <Icon name="clock-fading" size={18} class="inline" />
                      <span>
                        {formatDate(item.visitedAt)}
                      </span>
                    </div>
                    <div class="flex items-center gap-1">
                      <Icon name="calendar-plus" size={18} class="inline" />
                      <span>
                        {formatDate(item.createdAt)}
                      </span>
                    </div>
                    if (item.isPinned) {
                      <div class="ml-auto">
                        <Icon name="pinned" size={20} class="inline" />
                      </div>
                    }
                  </footer>
                </div>
              </article>
            }
          </div>
        </section>
      </main>
    </div>
  </div>

  <dialog id="my_modal" class="modal" {ref modal}>
    <div class="modal-box flex flex-col gap-y-4">
      <div class="flex gap-x-1">
        <div>
          <h3 class="text-lg font-bold tracking-tight">
            {editItem ? "Edit bookmark" : "Add a bookmark"}
          </h3>
          <h4 class="text-sm">
            {editItem
              ? "Update the information for this bookmark."
              : "Save a link with details to keep your collection organized."}
          </h4>
        </div>
        <figure class="ml-auto">
          if (getHostname(url) != "") {
            <img
              src={"https://www.google.com/s2/favicons?domain=" +
                `${getHostname(url)}/favicon.ico&sz=256`}
              alt=""
              class="h-12 rounded border px-1"
            />
          }
        </figure>
      </div>
      <label class="w-full mt-2">
        <span class="label font-semibold">"URL *"</span>
        <div class="flex gap-2">
          <div class="flex-1">
            <input
              type="url"
              {ref bindValue(urlRef)}
              placeholder="https://website.url"
              class={[
                "input input-bordered w-full",
                errors.url && "input-error",
              ]}
              maxLength={100}
              disabled={loading}
            />
            if (errors.url) {
              <span class="text-error block mt-1">
                {errors.url}
              </span>
            }
          </div>
          <button
            type="button"
            class="btn btn-ghost"
            onClick={fetchMeta}
            disabled={loading || !url}
            title="Fetch website metadata"
          >
            if (loading) {
              <span class="loading loading-spinner loading-md">{}</span>
            } else {
              <Icon name="sparkles" class="inline" />
            }
          </button>
        </div>
      </label>
      <label class="w-full">
        <span class="label font-semibold">"Title *"</span>
        <input
          type="text"
          {ref bindValue(titleRef)}
          placeholder="Website Title Here"
          class={[
            "input input-bordered w-full",
            errors.title && "input-error",
          ]}
          maxLength={100}
          disabled={loading}
        />
        if (errors.title) {
          <span class="text-error mt-1 block">
            {errors.title}
          </span>
        }
      </label>
      <label class="w-full">
        <span class="label font-semibold">"Description *"</span>
        <textarea
          {ref bindValue(descRef)}
          class={[
            "textarea border w-full",
            errors.description && "textarea-error",
          ]}
          placeholder="A very good long description"
          maxLength={280}
          disabled={loading}
        />
        <div class="flex justify-between items-center mt-1">
          <div class="flex-1">
            if (errors.description) {
              <span class="text-error block">
                {errors.description}
              </span>
            }
          </div>
          <span class="text-xs shrink-0">
            {desc.length}
            "/280"
          </span>
        </div>
      </label>
      <label class="w-full mb-2">
        <span class="label font-semibold">"Tags *"</span>
        <div
          class={[
            "flex flex-wrap items-center gap-2 p-2 border rounded-lg bg-base-100 min-h-12",
            errors.tags
              ? "border-error"
              : "border-base-content/20 focus-within:outline-2 focus-within:outline-offset-2 focus-within:outline-base-content/20",
          ]}
        >
          for (const tag of draftTags; key tag) {
            <span class="badge badge-primary gap-1">
              {tag}
              <button
                type="button"
                class="btn btn-ghost btn-xs btn-circle opacity-70 hover:opacity-100 min-h-0 h-4 w-4"
                onClick={() => {
                  draftTags = draftTags.filter((t) => t !== tag);
                }}
              >
                "✕"
              </button>
            </span>
          }
          <input
            type="text"
            {ref bindValue(tagRef)}
            placeholder={draftTags.length === 0 ? "Add filters (press Enter or comma)..." : ""}
            class="flex-1 bg-transparent outline-none min-w-30"
            disabled={loading}
            onKeyDown={(e: KeyboardEvent) => {
              if (e.key === "Enter" || e.key === ",") {
                e.preventDefault();
                const newTag = tag.trim();
                if (newTag && !draftTags.includes(newTag)) {
                  draftTags = [...draftTags, newTag];
                }
                tag = "";
              } else if (e.key === "Backspace" && tag === "" && draftTags.length > 0) {
                draftTags = draftTags.slice(0, -1);
              }
            }}
          />
        </div>
        if (errors.tags) {
          <span class="text-error mt-1 block">
            {errors.tags}
          </span>
        }
      </label>
      <form
        class="flex justify-end gap-3"
        onSubmit={async (e: Event) => {
          e.preventDefault();

          const result = v.safeParse(BookmarkFormSchema, {
            url: url,
            title: title,
            description: desc,
            tags: draftTags,
          });

          if (!result.success) {
            const flatErrors = v.flatten<typeof BookmarkFormSchema>(result.issues);
            errors = {
              url: flatErrors.nested?.url?.[0],
              title: flatErrors.nested?.title?.[0],
              description: flatErrors.nested?.description?.[0],
              tags: flatErrors.nested?.tags?.[0],
            };
            return;
          }

          errors = {};

          loading = true;
          let finalFavicon = favicon;
          if (!finalFavicon && getHostname(url)) {
            try {
              const res = await fetch(
                `https://images.weserv.nl/?url=${encodeURIComponent(
                  `https://www.google.com/s2/favicons?domain=${getHostname(url)}&sz=256`,
                )}`,
              );
              finalFavicon = await res.blob();
            } catch (e) {
              console.error("Failed to fetch google favicon:", e);
            }
          }
          loading = false;

          const isEdit = !!editItem;
          const inputData: Bookmark = {
            id: editItem?.id || `bm-${crypto.randomUUID()}`,
            title: title,
            url: url,
            hostname: getHostname(url),
            favicon: finalFavicon,
            description: desc,
            tags: draftTags,
            isPinned: editItem?.isPinned || false,
            isArchived: editItem?.isArchived || false,
            visitCount: editItem?.visitCount || 0,
            createdAt: editItem?.createdAt || Date.now(),
            visitedAt: editItem?.visitedAt || null,
          };
          saveBookmark(inputData);
          showToast(isEdit ? "Bookmark updated" : "Bookmark added", "success");
          modal?.close();
        }}
      >
        <button type="button" class="btn btn-outline" onClick={() => modal?.close()}>
          "Cancel"
        </button>
        <button type="submit" class="btn btn-primary">
          {editItem ? "Save Changes" : "Add Bookmark"}
        </button>
      </form>
    </div>
    <form method="dialog" class="modal-backdrop">
      <button>"Close"</button>
    </form>
  </dialog>
  <div class="toast toast-top toast-center z-100 select-none mt-16">
    for (const toast of toasts; key toast.id) {
      <div
        class={[
          "alert alert-soft",
          toastTypes[toast.type],
          "flex justify-between items-center",
          "relative pl-6",
        ]}
      >
        <button
          class="absolute top-1 left-1 opacity-50 hover:opacity-100 transition-opacity p-0.5"
          onClick={() => toastsMap.delete(toast.id)}
          aria-label="Close"
        >
          <Icon name="x" class="inline" size={12} />
        </button>
        <span>{toast.message}</span>
        if (toast.action) {
          <button
            class="btn btn-sm btn-ghost"
            onClick={() => {
              toast.action?.onClick();
              toastsMap.delete(toast.id);
            }}
          >
            {toast.action.label}
          </button>
        }
      </div>
    }
  </div>
}

