import Dexie, { type EntityTable } from "dexie";

export type Bookmark = {
  id: string;
  title: string;
  url: string;
  hostname: string;
  favicon: Blob | null;
  description: string;
  tags: string[];
  isPinned: boolean;
  isArchived: boolean;
  visitCount: number;
  createdAt: number;
  visitedAt: number | null;
};

export type ToastType = "info" | "success" | "warning" | "error";
export const toastTypes: Record<ToastType, string> = {
  info: "alert-info",
  success: "alert-success",
  warning: "alert-warning",
  error: "alert-error",
};
export type ToastData = {
  id: string;
  message: string;
  type: ToastType;
  action?: {
    label: string;
    onClick: () => void;
  };
};

export const tabOptions = ["Home", "Archived"] as const;
export type TabOption = (typeof tabOptions)[number];

export const sortOptions = ["Recently Added", "Recently Visited", "Most Visited"] as const;
export type SortOption = (typeof sortOptions)[number];

export const db = new Dexie("BookmarkDB") as Dexie & {
  bookmarks: EntityTable<Bookmark, "id">;
};

db.version(1).stores({
  bookmarks: "id, createdAt, visitCount",
});

