export function getHostname(url: string): string {
  try {
    if (!/^https?:\/\/(?:[\w-]+\.)+[a-zA-Z]{2,}(?:\/\S*)?$/.test(url)) return "";
    return new URL(url).hostname;
  } catch {
    return "";
  }
}

const blobCache = new WeakMap<Blob, string>();
export function getBlobUrl(blob: Blob | null): string {
  if (!blob) return "";
  const cached = blobCache.get(blob);
  if (cached) return cached;
  const url = URL.createObjectURL(blob);
  blobCache.set(blob, url);
  return url;
}

export function formatDate(timestamp?: string | number | Date | null): string {
  if (!timestamp) return "Never";
  return new Date(timestamp).toLocaleString("en-IN", {
    day: "numeric",
    month: "short",
  });
}
